const rows = $input.all().map(i => i.json);
if (!rows.length) return [];
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;');
const lines = rows.map(r => `<tr><td>${esc(r.lead_name || r.from_email)}</td><td>${esc(r.company)}</td><td>${esc(r.campaign_name)}</td><td>${esc((r.body || '').slice(0, 160))}</td></tr>`);
const html = `<b>${rows.length} interested ${rows.length === 1 ? 'reply' : 'replies'} in the last 24 hours</b>`
  + '<table><tr><th>Person</th><th>Company</th><th>Campaign</th><th>Reply</th></tr>' + lines.join('') + '</table>'
  + '<p>Answer them in Argorant: https://app.argorant.com/inbox</p>';
return [{ json: { html, count: rows.length } }];
